mapper.update:
update rtks_role_match_record
set `match`       = #{match},
    `update_time` = now()
where user_id = #{userId}
  and role_id = #{roleId}

mapper.select:
select count(1)
from rtks_role_match_record
where user_id = #{userId}
  and role_id = #{roleId}

select role_id
from rtks_role_match_record
where user_id = #{userId}

select count(id)
from rtks_role_match_record
where role_id = #{roleId}
  and user_id != #{userId}
  and `match` > #{match}
